import{describe,it,expect,beforeEach}from"vitest";import{InteractionTracker,EVENT_TYPES,MAX_EVENTS}from"../../frontend/js-modules/interaction-tracker.js";function fakeStorage(){const e=new Map;return{getItem:t=>e.has(t)?e.get(t):null,setItem:(t,a)=>e.set(t,a)}}describe("InteractionTracker",()=>{let e,t;beforeEach(()=>{e=fakeStorage(),t=new InteractionTracker({storage:e})}),it("starts empty",()=>{expect(t.getEvents()).toEqual([])}),it("records a valid event with an auto-assigned timestamp",()=>{t.track({type:EVENT_TYPES.VIEW,destinationId:"rec-goa"});const e=t.getEvents();expect(e).toHaveLength(1),expect(e[0].destinationId).toBe("rec-goa"),expect(typeof e[0].timestamp).toBe("number")}),it("preserves an explicitly provided timestamp",()=>{t.track({type:EVENT_TYPES.VIEW,destinationId:"rec-goa",timestamp:12345}),expect(t.getEvents()[0].timestamp).toBe(12345)}),it("rejects unknown event types",()=>{expect(()=>t.track({type:"not_a_real_type"})).toThrow()}),it("persists across tracker instances sharing the same storage",()=>{t.track({type:EVENT_TYPES.BOOKMARK,destinationId:"rec-ladakh"});const a=new InteractionTracker({storage:e});expect(a.getEvents()).toHaveLength(1)}),it("bounds the log to MAX_EVENTS, dropping the oldest first",()=>{for(let e=0;e<MAX_EVENTS+10;e++)t.track({type:EVENT_TYPES.VIEW,destinationId:`dest-${e}`});const e=t.getEvents();expect(e).toHaveLength(MAX_EVENTS),expect(e[0].destinationId).toBe("dest-10")}),it("clearEvents empties the log (reset preference profile)",()=>{t.track({type:EVENT_TYPES.RATING,destinationId:"rec-goa",rating:5}),t.clearEvents(),expect(t.getEvents()).toEqual([])})});